fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 1.0) {
        val formatted = if (seconds >= 10) {
            "${seconds.toLong()}s"
        } else {
            String.format("%.1f", seconds).trimEnd('0').trimEnd('.')
        }
        "$formatted" + "s"
    } else {
        val denominator = (1.0 / seconds).toLong()
        val safeDenom = denominator.coerceAtLeast(1)
        "1/${safeDenom}s"
    }
}

